const app=document.getElementById('phoneApp');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=v=>Array.isArray(v)?v:[];
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Math.abs(Number(n||0)));
const netMoney=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(n||0));
const validRoutes=['home','ledgers','outstanding','reports','search','more'];
let initialRoute=(location.hash||'#home').slice(1); if(!validRoutes.includes(initialRoute))initialRoute='home';
let invoiceLoadSeq=0;
const S={connected:false,tallyOnline:false,boot:null,company:localStorage.tbHybridCompany||localStorage.tbLiveCompany||'',route:initialRoute,ledgers:null,receivable:null,payable:null,sales:null,purchases:null,summary:null,sync:null,searchIndex:null,banks:null,ageing:null,todayDispatch:null,currentCustomer:null,loading:'',error:'',modal:null,currentInvoice:null,pdfURL:''};
let outType='receivable';
let ledgerTab='ledgers';
let currentLedgerReport=null;
let currentGroupReport=null;
const ICON={home:'<path d="M3 11l9-8 9 8v9a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',ledgers:'<path d="M4 4h16v16H4z"/><path d="M8 8h8M8 12h8M8 16h5"/>',outstanding:'<path d="M4 19V5M4 19h16M8 15l3-4 3 2 5-7"/>',reports:'<path d="M5 20V9M10 20V4M15 20v-7M20 20V7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',search:'<circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/>',money:'<path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7H14a3.5 3.5 0 0 1 0 7H6"/>',sales:'<path d="M4 18l5-5 4 3 7-9"/><path d="M15 7h5v5"/>',wifi:'<path d="M2 8a15 15 0 0 1 20 0M5 12a10 10 0 0 1 14 0M8.5 15.5a5 5 0 0 1 7 0"/><circle cx="12" cy="20" r="1"/>',x:'<path d="M6 6l12 12M18 6L6 18"/>',refresh:'<path d="M20 6v5h-5M4 18v-5h5"/><path d="M18.4 9A7 7 0 0 0 6 6.5L4 11M5.6 15A7 7 0 0 0 18 17.5l2-4.5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',file:'<path d="M6 2h8l4 4v16H6z"/><path d="M14 2v5h5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${ICON[n]||ICON.file}</svg>`;
function toast(msg,err=false){const e=document.createElement('div');e.className='toast'+(err?' err':'');e.textContent=msg;document.body.appendChild(e);setTimeout(()=>e.remove(),3400)}
function creds(){return{id:localStorage.tbLiveDeviceId||localStorage.tbHybridDeviceId||'',key:localStorage.tbLiveDeviceKey||localStorage.tbHybridDeviceKey||''}}
function saveCreds(id,key){localStorage.tbLiveDeviceId=id;localStorage.tbLiveDeviceKey=key;localStorage.tbHybridDeviceId=id;localStorage.tbHybridDeviceKey=key}
function clearCreds(){['tbLiveDeviceId','tbLiveDeviceKey','tbHybridDeviceId','tbHybridDeviceKey'].forEach(k=>localStorage.removeItem(k));['tbPhonePinSalt','tbPhonePinHash','tbPhoneLocked','tbPhonePinFails','tbPhonePinBlockedUntil'].forEach(k=>localStorage.removeItem(k))}
function hasPhonePin(){return !!(localStorage.tbPhonePinSalt&&localStorage.tbPhonePinHash)}
function phoneIsLocked(){return hasPhonePin()&&localStorage.tbPhoneLocked!=='0'}
function markPhoneLocked(){if(hasPhonePin())localStorage.tbPhoneLocked='1'}
function bytesHex(a){return[...a].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function pinHash(pin,saltHex){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:hexBytes(saltHex),iterations:120000},key,256);return bytesHex(new Uint8Array(bits))}
function renderPinSetup(){app.innerHTML=`<div class="offline-wrap"><div class="offline-card"><div class="offline-icon">${icon('lock')}</div><h2>Secure this phone</h2><p class="mobile-sub">Create a 4–6 digit app PIN. TallyBridge will lock whenever the phone app is closed or sent to the background.</p><input id="newPhonePin" class="input pair-input" type="password" inputmode="numeric" autocomplete="new-password" maxlength="6" placeholder="4–6 digit PIN"><input id="newPhonePin2" class="input pair-input" type="password" inputmode="numeric" autocomplete="new-password" maxlength="6" placeholder="Repeat PIN"><button class="btn full-btn" data-action="set-pin">Set app PIN</button><div id="lockErr" class="error-banner" style="display:none;margin-top:10px"></div></div></div>`}
function renderLocked(msg=''){app.innerHTML=`<div class="offline-wrap"><div class="offline-card"><div class="offline-icon">${icon('lock')}</div><div class="status-pill warn"><span class="dot"></span>APP LOCKED</div><h2>Unlock TallyBridge</h2><p class="mobile-sub">Enter your phone app PIN. Pairing stays saved on this device.</p><input id="unlockPhonePin" class="input pair-input" type="password" inputmode="numeric" autocomplete="current-password" maxlength="6" placeholder="PIN">${msg?`<div class="error-banner">${esc(msg)}</div>`:''}<button class="btn full-btn" data-action="unlock">Unlock</button><button class="btn secondary full-btn" data-action="reset-lock" style="margin-top:9px">Reset app & pair again</button></div></div>`}
async function setPhonePin(){const a=document.getElementById('newPhonePin')?.value||'',b=document.getElementById('newPhonePin2')?.value||'',err=document.getElementById('lockErr');if(!/^\d{4,6}$/.test(a)){if(err){err.style.display='block';err.textContent='Use a 4–6 digit numeric PIN.'}return}if(a!==b){if(err){err.style.display='block';err.textContent='PINs do not match.'}return}const salt=new Uint8Array(16);crypto.getRandomValues(salt);const saltHex=bytesHex(salt),hash=await pinHash(a,saltHex);localStorage.tbPhonePinSalt=saltHex;localStorage.tbPhonePinHash=hash;localStorage.tbPhoneLocked='0';localStorage.tbPhonePinFails='0';await boot(false,true)}
async function unlockPhone(){const blocked=Number(localStorage.tbPhonePinBlockedUntil||0);if(blocked>Date.now()){renderLocked(`Too many attempts. Try again in ${Math.ceil((blocked-Date.now())/1000)} seconds.`);return}const pin=document.getElementById('unlockPhonePin')?.value||'';const hash=await pinHash(pin,localStorage.tbPhonePinSalt||'');if(hash!==localStorage.tbPhonePinHash){let fails=Number(localStorage.tbPhonePinFails||0)+1;localStorage.tbPhonePinFails=String(fails);if(fails>=5){localStorage.tbPhonePinBlockedUntil=String(Date.now()+30000);localStorage.tbPhonePinFails='0';renderLocked('Too many incorrect PIN attempts. Locked for 30 seconds.')}else renderLocked(`Incorrect PIN. ${5-fails} attempts remaining.`);return}localStorage.tbPhoneLocked='0';localStorage.tbPhonePinFails='0';localStorage.removeItem('tbPhonePinBlockedUntil');await boot(false,true)}
// A fresh page/PWA launch is always locked when a PIN exists.
if(hasPhonePin())markPhoneLocked();
function hexBytes(hex){if(!hex||hex.length%2)return new Uint8Array();const a=new Uint8Array(hex.length/2);for(let i=0;i<a.length;i++)a[i]=parseInt(hex.slice(i*2,i*2+2),16);return a}
async function shaHex(text){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function hmacHex(keyHex,text){const key=await crypto.subtle.importKey('raw',hexBytes(keyHex),{name:'HMAC',hash:'SHA-256'},false,['sign']);const sig=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(text));return[...new Uint8Array(sig)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function nonce(){const a=new Uint8Array(16);crypto.getRandomValues(a);return[...a].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function signed(path,opts={}){const c=creds();if(!c.id||!c.key)throw Object.assign(new Error('Phone is not paired'),{auth:true});const method=(opts.method||'GET').toUpperCase(),body=opts.body||'',ts=Math.floor(Date.now()/1000).toString(),n=nonce(),bh=await shaHex(body),msg=[method,path,ts,n,bh].join('\n'),sig=await hmacHex(c.key,msg);const r=await fetch(path,{...opts,signal:opts.signal||AbortSignal.timeout(45000),method,body:method==='GET'?undefined:body,cache:'no-store',headers:{'Content-Type':'application/json','X-TB-Device':c.id,'X-TB-Time':ts,'X-TB-Nonce':n,'X-TB-Signature':sig,...(opts.headers||{})}});const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{d={error:t}}if(!r.ok){const e=new Error(d.error||`HTTP ${r.status}`);e.status=r.status;if(r.status===401){e.auth=true;e.revoked=(d.error==='device not authorized')}if(r.status===429||r.status===503)e.tally=true;if(r.status===404)e.noSaved=true;throw e}return d}
async function signedBlob(path){const c=creds();if(!c.id||!c.key)throw Object.assign(new Error('Phone is not paired'),{auth:true});const method='GET',body='',ts=Math.floor(Date.now()/1000).toString(),n=nonce(),bh=await shaHex(body),msg=[method,path,ts,n,bh].join('\n'),sig=await hmacHex(c.key,msg);const r=await fetch(path,{method,signal:AbortSignal.timeout(50000),cache:'no-store',headers:{'X-TB-Device':c.id,'X-TB-Time':ts,'X-TB-Nonce':n,'X-TB-Signature':sig}});if(!r.ok){const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{d={error:t}}const e=new Error(d.error||`HTTP ${r.status}`);e.status=r.status;if(r.status===401){e.auth=true;e.revoked=(d.error==='device not authorized')}throw e}return r.blob()}
async function publicStatus(){const r=await fetch('/api/v1/public/live',{cache:'no-store'});if(!r.ok)throw new Error('Bridge unavailable');return r.json()}
async function showPairAfterRevocation(){clearCreds();clearViewData();S.connected=true;S.boot=null;S.sync=null;S.summary=null;S.tallyOnline=false;try{const p=await publicStatus();S.tallyOnline=!!p.tallyOnline;renderPair(p)}catch(e){S.connected=false;renderBridgeOffline('This phone was revoked. Start TallyBridge on the Windows PC to pair again.')}}
async function verifyDeviceAuthorization(){const c=creds();if(!c.id||!c.key)return false;try{await signed('/api/v1/mobile/auth-check');return true}catch(e){if(e.revoked){await showPairAfterRevocation();return false}if(e.auth){S.connected=true;renderAuthProblem(e.message);return false}throw e}}
function sourceOf(x){return x?.live?'live':(x?.source==='saved'||x?.stale?'saved':'none')}
function stamp(x){if(!x?.fetchedAt)return'NOT UPDATED YET';const d=new Date(x.fetchedAt);return sourceOf(x)==='live'?`LIVE • ${d.toLocaleString()}`:`LAST UPDATED • ${d.toLocaleString()}`}
function dataBanner(x){if(!x)return'';if(sourceOf(x)==='live')return`<div class="live-banner"><b>Live from TallyPrime</b> • ${esc(new Date(x.fetchedAt).toLocaleTimeString())}</div>`;return`<div class="saved-banner"><b>Showing last updated data</b> • ${esc(new Date(x.fetchedAt).toLocaleString())}${x.liveError?`<div class="saved-reason">Live refresh unavailable: ${esc(x.liveError)}</div>`:''}</div>`}
function updateConnectionFrom(x){if(x?.tallyOnline===true||x?.live===true)S.tallyOnline=true;else if(x?.tallyOnline===false)S.tallyOnline=false;updateTopBadge()}
function clearViewData(){invoiceLoadSeq++;clearPDFURL();S.currentInvoice=null;currentLedgerReport=null;currentGroupReport=null;S.error='';S.ledgers=S.receivable=S.payable=S.sales=S.purchases=S.summary=S.searchIndex=S.banks=S.ageing=S.todayDispatch=S.currentCustomer=null;S.modal=null}
async function boot(quiet=false,bypassLock=false){let c=creds();if(c.id){try{const ok=await verifyDeviceAuthorization();if(!ok)return}catch(e){S.connected=false;renderBridgeOffline(e.message||'Cannot reach Windows bridge.');return}c=creds();if(!c.id)return;if(!bypassLock){if(!hasPhonePin()){renderPinSetup();return}if(phoneIsLocked()){renderLocked();return}}}if(!c.id){try{const p=await publicStatus();S.connected=true;S.tallyOnline=!!p.tallyOnline;renderPair(p)}catch(e){S.connected=false;renderBridgeOffline('Windows TallyBridge is not reachable through Tailscale.')}return}
const wasConnected=S.connected;
try{const b=await signed('/api/v1/mobile/bootstrap');S.connected=true;S.boot=b;S.sync=b.autoSync||S.sync;S.tallyOnline=!!b.tallyOnline;const cs=arr(b.companies);if(!cs.some(x=>x.name===S.company)){S.company=cs[0]?.name||''}if(S.company){localStorage.tbHybridCompany=S.company;localStorage.tbLiveCompany=S.company}S.summary=(b.summaries||{})[S.company]||null;if(!quiet||!wasConnected){renderRoute();ensureRouteData()}else{updateTopBadge();if(S.route==='home')renderRoute()}return b}catch(e){if(e.auth){S.connected=true;renderAuthProblem(e.message);return}S.connected=false;renderBridgeOffline(e.message||'Cannot reach Windows bridge.');throw e}}
function renderBridgeOffline(detail=''){app.innerHTML=`<div class="offline-wrap"><div class="offline-card"><div class="offline-icon">${icon('wifi')}</div><div class="status-pill err"><span class="dot"></span>BRIDGE OFFLINE</div><h2>PC connection unavailable</h2><p class="mobile-sub">The app keeps your pairing. Start TallyBridge on the Windows PC and make sure Tailscale is connected.</p>${detail?`<div class="error-banner" style="margin-top:14px">${esc(detail)}</div>`:''}<button class="btn full-btn" data-action="retry" style="margin-top:12px">Retry connection</button></div></div>`}
function renderAuthProblem(detail){app.innerHTML=`<div class="offline-wrap"><div class="offline-card"><div class="offline-icon">${icon('lock')}</div><h2>Phone authorization needs attention</h2><p class="mobile-sub">Your pairing is kept unless you choose Reset pairing.</p><div class="error-banner" style="margin-top:12px">${esc(detail)}</div><button class="btn full-btn" data-action="retry">Retry</button><button class="btn secondary full-btn" data-action="unpair" style="margin-top:9px">Reset pairing</button></div></div>`}
function renderPair(p){app.innerHTML=`<div class="pair-wrap"><div class="pair-card"><div class="phone-brand" style="color:#071b38;margin-bottom:18px"><div class="brandmark">TB</div><div>TallyBridge<small style="color:#66758a">HYBRID • READ ONLY</small></div></div><div class="status-pill ok"><span class="dot"></span>BRIDGE ONLINE</div><h2>Pair this phone</h2><p class="mobile-sub">On Windows open <b>Devices → Generate pairing code</b>. Pairing does not depend on Tally being live.</p>${p?.tallyOnline?'<div class="notice ok" style="margin:12px 0">TallyPrime is live right now.</div>':'<div class="notice warn" style="margin:12px 0">Tally is not verified live right now. You can still pair and use saved last-updated data.</div>'}<input id="pairCode" class="input pair-input" maxlength="6" inputmode="numeric" placeholder="000000"><input id="pairName" class="input" style="width:100%;margin-bottom:9px" value="My phone" placeholder="Phone name"><button class="btn full-btn" data-action="pair">Pair phone</button><div id="pairErr" class="error-banner" style="display:none;margin-top:10px"></div></div></div>`}
async function doPair(){const code=document.getElementById('pairCode')?.value.trim(),name=document.getElementById('pairName')?.value.trim()||'Phone';try{const r=await fetch('/api/v1/pair',{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({code,name})});const t=await r.text();let d={};try{d=JSON.parse(t)}catch{}if(!r.ok)throw new Error(d.error||t||'Pairing failed');saveCreds(d.deviceId,d.deviceKey);localStorage.tbPhoneLocked='1';renderPinSetup()}catch(e){const el=document.getElementById('pairErr');if(el){el.style.display='block';el.textContent=e.message}}}
function renderTop(){const cs=arr(S.boot?.companies);const syncing=!!S.sync?.running;const state=syncing?'SYNCING':(S.tallyOnline?'TALLY LIVE':'LAST UPDATED');return`<header class="phone-top"><div class="phone-top-row"><div class="phone-brand"><div class="brandmark">TB</div><div>TallyBridge<small>AUTO SYNC • READ ONLY</small></div></div><div id="liveBadge" class="phone-live ${S.tallyOnline&&!syncing?'':'saved'}"><span class="dot"></span>${state}</div></div><select id="companySelect" class="company-select">${cs.length?cs.map(c=>`<option value="${esc(c.name)}" ${c.name===S.company?'selected':''}>${esc(c.name)}</option>`).join(''):'<option value="">Waiting for Tally company…</option>'}</select></header>`}
function updateTopBadge(){const e=document.getElementById('liveBadge');if(!e)return;const syncing=!!S.sync?.running;e.className='phone-live'+(S.tallyOnline&&!syncing?'':' saved');e.innerHTML=`<span class="dot"></span>${syncing?'SYNCING':(S.tallyOnline?'TALLY LIVE':'LAST UPDATED')}`}
function navItem(k,label){return`<button class="nav-item ${S.route===k?'active':''}" data-route="${k}">${icon(k)}<span>${label}</span></button>`}
function shell(content){return`<div class="phone-shell">${renderTop()}<main class="phone-content">${content}</main><nav class="bottom-nav">${navItem('home','Home')}${navItem('ledgers','Ledgers')}${navItem('outstanding','Outstanding')}${navItem('reports','Reports')}${navItem('more','More')}</nav></div>${S.modal||''}`}
function syncBusy(){if(!S.sync?.running)return false;const t=Date.parse(S.sync.startedAt||'');return !Number.isFinite(t)||Date.now()-t<45000}
function summaryCard(label,val,sub,kind,when){const syncing=syncBusy();const display=kind==='status'?(S.connected?'Connected':'Offline'):(val==null?(syncing?'Fetching…':'Not updated'):netMoney(val));const timeLine=kind==='status'?'PC bridge':(when?`Updated ${new Date(when).toLocaleString()}`:(S.sync?.lastError?'Automatic sync will retry':'Waiting for first automatic sync'));return`<div class="summary-card"><div class="k">${esc(label)}</div><div class="v">${esc(display)}</div><div class="s">${esc(sub||'Updates automatically')}</div><div class="s">${esc(timeLine)}</div></div>`}
function homeView(){const sm=S.summary,sync=S.sync||S.boot?.autoSync||{},busy=syncBusy();const syncLine=sync.running?`<div class="live-banner"><b>Updating automatically from TallyPrime…</b> ${esc(sync.company||S.company||'')} ${sync.step?'• '+esc(sync.step):''}</div>`:(sync.lastError?`<div class="saved-banner"><b>Using last updated data.</b> Automatic live refresh will retry. <div class="saved-reason">${esc(sync.lastError)}</div></div>`:(S.tallyOnline?'<div class="live-banner"><b>TallyPrime is live.</b> Data refreshes automatically in the background.</div>':'<div class="saved-banner"><b>Last updated mode.</b> The phone stays usable and automatic sync retries when Tally is available.</div>'));return shell(`<div class="mobile-title">Overview</div><div class="mobile-sub">${esc(S.company||'Waiting for company detection')}</div>${syncLine}<div class="refresh-row"><span class="live-stamp">${sm?stamp(sm):(busy?'UPDATING AUTOMATICALLY':(sync.lastError?'NOT UPDATED • RETRYING':'WAITING FOR FIRST SYNC'))}</span><span class="status-pill ${busy?'warn':'ok'}">${busy?'SYNCING':'AUTO SYNC'}</span></div>${S.error?`<div class="error-banner">${esc(S.error)}</div>`:''}<div class="summary-grid">${summaryCard('Receivable',sm?.receivable,sm?.rCount!=null?`${sm.rCount} parties`:'Automatic','receivable',sm?.rFetchedAt)}${summaryCard('We Need to Pay',sm?.payable,sm?.pCount!=null?`${sm.pCount} parties`:'Automatic','payable',sm?.pFetchedAt)}${summaryCard('Sales This Month',sm?.sales,sm?.sCount!=null?`${sm.sCount} vouchers`:'Automatic','sales-month',sm?.sFetchedAt)}${summaryCard('Bridge',0,S.connected?'Connected to PC':'Disconnected','status')}</div><div class="mobile-section">Quick actions</div><div class="quick-grid"><button class="quick-btn" data-route="search"><span class="qi">${icon('search')}</span><b>Universal Search</b></button><button class="quick-btn" data-route="ledgers"><span class="qi">${icon('ledgers')}</span><b>Find Ledger</b></button><button class="quick-btn" data-action="today-dispatch"><span class="qi">${icon('sales')}</span><b>Today’s Dispatch</b></button><button class="quick-btn" data-route="outstanding"><span class="qi">${icon('money')}</span><b>Outstanding</b></button><button class="quick-btn" data-action="open-ageing"><span class="qi">${icon('reports')}</span><b>Ageing</b></button><button class="quick-btn" data-route="reports"><span class="qi">${icon('reports')}</span><b>Reports</b></button></div>`)}
async function requestAutoSync(reason='phone'){if(!S.connected||!S.company||!creds().id)return;try{const x=await signed('/api/v1/mobile/sync',{method:'POST',body:JSON.stringify({company:S.company,reason})});S.sync=x.autoSync||S.sync;updateTopBadge()}catch(e){if(e.auth)renderAuthProblem(e.message)}}
async function refreshOne(kind){if(!S.company)throw new Error('No company selected');let x;if(kind==='receivable')x=await signed('/api/v1/mobile/outstanding?company='+encodeURIComponent(S.company)+'&type=receivable&refresh=1');else if(kind==='payable')x=await signed('/api/v1/mobile/outstanding?company='+encodeURIComponent(S.company)+'&type=payable&refresh=1');else if(kind==='sales-month')x=await signed('/api/v1/mobile/vouchers?company='+encodeURIComponent(S.company)+'&type=sales&period=month&refresh=1');else throw new Error('Unknown refresh');if(x.live)S.tallyOnline=true;else if(x.source==='saved')S.tallyOnline=false;return x}
function mergeSummary(kind,x){S.summary=S.summary||{source:x.live?'live':'saved',live:!!x.live,fetchedAt:x.fetchedAt};if(kind==='receivable'){S.summary.receivable=x.total;S.summary.rCount=x.count;S.summary.rFetchedAt=x.fetchedAt}else if(kind==='payable'){S.summary.payable=x.total;S.summary.pCount=x.count;S.summary.pFetchedAt=x.fetchedAt}else{S.summary.sales=x.total;S.summary.sCount=x.count;S.summary.sFetchedAt=x.fetchedAt}S.summary.fetchedAt=x.fetchedAt;S.summary.live=!!x.live;S.summary.source=x.live?'live':'saved';S.summary.liveError=x.liveError||''}
async function loadOne(kind){if(kind==='status'||S.loading)return;S.loading=kind;S.error='';renderRoute();try{const x=await refreshOne(kind);mergeSummary(kind,x);if(!x.live)S.error='Tally could not refresh; showing the last updated value.'}catch(e){S.error=e.message}finally{S.loading='';renderRoute()}}
async function loadSummary(){if(S.loading)return;S.loading='summary';S.error='';renderRoute();try{for(const kind of ['receivable','payable','sales-month']){const x=await refreshOne(kind);mergeSummary(kind,x);if(!x.live){S.error='Live refresh stopped for Tally safety. Remaining cards keep their last updated values.';break}}}catch(e){S.error=e.message}finally{S.loading='';renderRoute()}}
function ledgerGroups(){const m=new Map();for(const x of arr(S.ledgers?.ledgers)){const g=(x.parent||'').trim();if(!g)continue;m.set(g,(m.get(g)||0)+1)}return [...m.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([name,count])=>({name,count}))}
function ledgersView(){const x=S.ledgers,sync=S.sync||{},busy=syncBusy();const isGroups=ledgerTab==='groups';return shell(`<div class="route-title"><div><h2>Ledgers</h2><div class="live-stamp">${stamp(x)}</div></div><span class="status-pill ${busy?'warn':'ok'}">${busy?'AUTO UPDATING':'AUTO SYNC'}</span></div><div class="tabs"><button class="tab ${!isGroups?'active':''}" data-action="ledger-tab" data-type="ledgers">Ledgers</button><button class="tab ${isGroups?'active':''}" data-action="ledger-tab" data-type="groups">Groups</button></div>${dataBanner(x)}<input id="ledgerSearch" class="search" placeholder="${isGroups?'Search ledger groups…':'Search ledger list…'}" autocomplete="off"><div class="no-stale" style="margin:-4px 2px 10px">${isGroups?'Groups are taken from your Tally ledger structure. Tap a group to see balances and share it.':'Search is instant from the last downloaded ledger index. Tap a ledger for statement/outstanding sharing.'}</div>${S.error?`<div class="error-banner">${esc(S.error)}</div>`:''}<div id="ledgerList">${x?(isGroups?renderGroupRows(ledgerGroups()):renderLedgerRows(x.ledgers)):`<div class="empty">${busy?'Fetching ledger index automatically from TallyPrime…':(sync.lastError?'Ledger index is not updated yet. Automatic sync will retry.':'Waiting for first automatic ledger sync…')}</div>`}</div>`)}
function renderLedgerRows(xs,q=''){const f=arr(xs).filter(x=>!q||`${x.name} ${x.parent}`.toLowerCase().includes(q.toLowerCase())).slice(0,150);return f.length?f.map(x=>`<button class="row-card" style="width:100%;text-align:left" data-action="ledger-open" data-ledger="${esc(x.name)}"><div class="row-main"><div class="row-title">${esc(x.name)}</div><div class="row-meta">${esc(x.parent||'')}</div></div><span style="color:#718097">›</span></button>`).join(''):'<div class="empty">No matching ledgers.</div>'}
function renderGroupRows(xs,q=''){const f=arr(xs).filter(x=>!q||x.name.toLowerCase().includes(q.toLowerCase())).slice(0,150);return f.length?f.map(x=>`<button class="row-card" style="width:100%;text-align:left" data-action="group-open" data-group="${esc(x.name)}"><div class="row-main"><div class="row-title">${esc(x.name)}</div><div class="row-meta">${x.count} ledger${x.count===1?'':'s'} in index</div></div><span style="color:#718097">›</span></button>`).join(''):'<div class="empty">No matching groups.</div>'}
async function loadSavedLedgers(){if(S.ledgers||!S.company)return;try{S.ledgers=await signed('/api/v1/mobile/ledgers?company='+encodeURIComponent(S.company));renderRoute()}catch(e){if(!e.noSaved)S.error=e.message}}
async function loadLedgers(){if(S.loading)return;S.loading='ledgers';S.error='';renderRoute();try{S.ledgers=await signed('/api/v1/mobile/ledgers?company='+encodeURIComponent(S.company)+'&refresh=1');S.tallyOnline=!!S.ledgers.live;if(!S.ledgers.live)S.error='Live refresh failed; showing saved ledger index.'}catch(e){S.error=e.message}finally{S.loading='';renderRoute()}}
function outstandingView(){const x=outType==='payable'?S.payable:S.receivable,sync=S.sync||{},busy=syncBusy();return shell(`<div class="route-title"><div><h2>${outType==='payable'?'We Need to Pay':'Outstanding'}</h2><div class="live-stamp">${stamp(x)}</div></div><span class="status-pill ${busy?'warn':'ok'}">${busy?'AUTO UPDATING':'AUTO SYNC'}</span></div><div class="tabs"><button class="tab ${outType==='receivable'?'active':''}" data-action="out-tab" data-type="receivable">Receivable</button><button class="tab ${outType==='payable'?'active':''}" data-action="out-tab" data-type="payable">Payable</button></div>${dataBanner(x)}${S.error?`<div class="error-banner">${esc(S.error)}</div>`:''}${x?`<div class="mobile-card"><div class="metric-label">Total ${outType}</div><div style="font-size:25px;font-weight:900;margin-top:5px">${netMoney(x.total)}</div><div class="row-meta">${x.count} ledger${x.count===1?'':'s'}</div></div>${renderOutstandingParties(x.parties||x.bills)}`:`<div class="empty">${busy?'Fetching outstanding automatically…':(sync.lastError?'Outstanding is not updated yet. Automatic sync will retry safely.':'Waiting for first automatic outstanding sync…')}</div>`}`)}
function renderBills(xs,granularity){return arr(xs).length?arr(xs).map(b=>{const party=esc(b.party||'Unknown party');if(granularity==='party')return`<button class="row-card row-button" data-action="party-outstanding" data-party="${party}"><div class="row-main"><div class="row-title">${party}</div><div class="row-meta">Tap for bill-wise details</div></div><div class="row-amount">${money(b.pendingAmount)}</div></button>`;return`<div class="row-card"><div class="row-main"><div class="row-title">${party}</div><div class="row-meta">${esc(b.billNumber||'')} ${b.dueDate?'• Due '+esc(b.dueDate):''}</div></div><div class="row-amount">${money(b.pendingAmount)}</div></div>`}).join(''):'<div class="empty">No outstanding rows.</div>'}
function renderOutstandingParties(xs){return arr(xs).length?arr(xs).map(p=>{const party=esc(p.party||p.ledger||'Unknown ledger');const amount=Number(p.amount??p.pendingAmount??0);return`<button class="row-card row-button" data-action="party-outstanding" data-party="${party}"><div class="row-main"><div class="row-title">${party}</div><div class="row-meta">${esc(p.parent||'')} ${p.parent?'• ':''}Tap for bill-wise details</div></div><div class="row-amount">${money(amount)} ${esc(p.drCr||'')}</div></button>`}).join(''):'<div class="empty">No outstanding ledgers.</div>'}
async function loadSavedOutstanding(){const key=outType==='payable'?'payable':'receivable';if(S[key]||!S.company)return;try{S[key]=await signed('/api/v1/mobile/outstanding?company='+encodeURIComponent(S.company)+'&type='+outType);renderRoute()}catch(e){if(!e.noSaved)S.error=e.message}}
async function loadOutstanding(){if(S.loading)return;S.loading='outstanding';S.error='';renderRoute();try{const x=await signed('/api/v1/mobile/outstanding?company='+encodeURIComponent(S.company)+'&type='+outType+'&refresh=1');if(outType==='payable')S.payable=x;else S.receivable=x;S.tallyOnline=!!x.live;if(!x.live)S.error='Live refresh failed; showing last updated data.'}catch(e){S.error=e.message}finally{S.loading='';renderRoute()}}
async function openPartyOutstanding(party){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="screen-loader"><span class="spinner"></span>Loading bill-wise details for ${esc(party)}…</div></div></div>`;renderRoute();try{const x=await signed('/api/v1/mobile/party-outstanding?company='+encodeURIComponent(S.company)+'&type='+outType+'&party='+encodeURIComponent(party));S.tallyOnline=!!x.live;const note=x.summaryOnly?`<div class="notice info">Tally did not return a bill-wise breakup for this ledger. The total outstanding is taken from the safe ledger balance index instead of showing a false ₹0.</div>`:'';S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${esc(party)}</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}${note}<div class="mobile-card"><div class="metric-label">Outstanding</div><div style="font-size:24px;font-weight:900">${money(x.total)}</div><div class="row-meta">${x.count?`${x.count} bill row${x.count===1?'':'s'}`:'Ledger balance'}</div></div>${x.count?renderBills(x.bills,'bill'):'<div class="empty">Bill-wise breakup is unavailable, but the ledger outstanding total above is preserved.</div>'}</div></div>`}catch(e){toast(e.message,true);S.modal=null}finally{renderRoute()}}
function reportsView(){return shell(`<div class="mobile-title">Reports</div><div class="mobile-sub">Registers and customer reports use live data when available and the last successful copy when Tally is temporarily unavailable.</div><div class="mobile-section">Daily work</div><div class="report-grid"><button class="report-btn" data-action="today-dispatch">Today’s Dispatch</button><button class="report-btn" data-action="open-ageing">Outstanding Ageing</button><button class="report-btn" data-route="search">Universal Search</button><button class="report-btn" data-route="ledgers">Customer 360</button></div><div class="mobile-section">Registers</div><div class="report-grid"><button class="report-btn" data-action="report" data-report="sales">Sales Register</button><button class="report-btn" data-action="report" data-report="purchases">Purchase Register</button><button class="report-btn" data-action="report" data-report="Day Book">Day Book</button><button class="report-btn" data-action="goto-payable">Bills Payable</button></div><div class="mobile-section">Accounting reports</div><div class="report-grid"><button class="report-btn" data-action="report" data-report="Trial Balance">Trial Balance</button><button class="report-btn" data-action="report" data-report="Profit and Loss">P&amp;L</button><button class="report-btn" data-action="report" data-report="Balance Sheet">Balance Sheet</button><button class="report-btn" data-route="outstanding">Bills Receivable</button></div><div class="notice info" style="margin-top:14px">Sales and Purchase Registers open financial-year months → vouchers → full voucher details. Customer-facing PDFs can include a selected Tally bank account.</div>`)}
async function openReport(name){if(S.loading)return;S.loading='report';S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="screen-loader"><span class="spinner"></span>Loading ${esc(name)}…</div></div></div>`;renderRoute();try{let x;if(name==='sales'){x=await signed('/api/v1/mobile/vouchers?company='+encodeURIComponent(S.company)+'&type=sales&period=fy&refresh=1');S.sales=x;currentRegister='sales';S.modal=renderRegister('sales',x)}else if(name==='purchases'){x=await signed('/api/v1/mobile/vouchers?company='+encodeURIComponent(S.company)+'&type=purchase&period=fy&refresh=1');S.purchases=x;currentRegister='purchase';S.modal=renderRegister('purchase',x)}else{x=await signed('/api/v1/mobile/report?company='+encodeURIComponent(S.company)+'&name='+encodeURIComponent(name));S.modal=renderGenericSheet(name,x)}S.tallyOnline=!!x.live}catch(e){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h3>${esc(name)}</h3><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div><div class="error-banner">${esc(e.message)}</div></div></div>`}finally{S.loading='';renderRoute()}}
function monthLabel(key){if(!/^\d{4}-\d{2}$/.test(key||''))return key||'Unknown';const [y,m]=key.split('-').map(Number);return new Date(y,m-1,1).toLocaleString(undefined,{month:'long',year:'numeric'})}
function fyMonthKeys(){const now=new Date(),startYear=(now.getMonth()+1)<4?now.getFullYear()-1:now.getFullYear(),out=[];for(let i=0;i<12;i++){const d=new Date(startYear,3+i,1);out.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)}return out}
let currentRegister='sales';
function renderRegister(kind,x){const title=kind==='purchase'?'Purchase Register':'Sales Register',grouped={};for(const v of arr(x.vouchers)){const k=(v.date||'').slice(0,7);if(!/^\d{4}-\d{2}$/.test(k))continue;if(!grouped[k])grouped[k]={amount:0,count:0};grouped[k].amount+=Math.abs(Number(v.amount||0));grouped[k].count++}const keys=fyMonthKeys();return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${title}</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}<div class="mobile-card"><div class="metric-label">Financial Year ${kind==='purchase'?'Purchases':'Sales'}</div><div style="font-size:24px;font-weight:900">${money(x.total)}</div><div class="row-meta">${x.count} vouchers • tap a month</div></div>${keys.map(k=>{const g=grouped[k]||{amount:0,count:0};return`<button class="row-card row-button" data-action="register-month-open" data-kind="${kind}" data-month="${esc(k)}"><div class="row-main"><div class="row-title">${esc(monthLabel(k))}</div><div class="row-meta">${g.count} voucher${g.count===1?'':'s'}</div></div><div class="row-amount">${money(g.amount)}</div></button>`}).join('')}</div></div>`}
function renderSalesRegister(x){return renderRegister('sales',x)}
function renderPurchaseRegister(x){return renderRegister('purchase',x)}
function openRegisterMonth(kind,month){const data=kind==='purchase'?S.purchases:S.sales,xs=arr(data?.vouchers).filter(v=>(v.date||'').slice(0,7)===month).sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.number).localeCompare(String(b.number)));const total=xs.reduce((a,v)=>a+Math.abs(Number(v.amount||0)),0),label=kind==='purchase'?'Purchase':'Sales';currentRegister=kind;S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${esc(monthLabel(month))} • ${label}</h3><div class="row-meta">${xs.length} vouchers • ${money(total)}</div></div><button class="icon-btn" data-action="register-back">‹</button></div>${xs.length?xs.map(v=>`<button class="row-card row-button" data-action="invoice-open" data-master="${esc(v.masterId||'')}" data-number="${esc(v.number||'')}" data-date="${esc(v.date||'')}" data-party="${esc(v.party||'')}" data-amount="${esc(v.amount||0)}"><div class="row-main"><div class="row-title">${esc(v.number||'Voucher')}</div><div class="row-meta">${esc(v.date||'')} • ${esc(v.party||'')}</div></div><div class="row-amount">${money(v.amount)}</div></button>`).join(''):'<div class="empty">No vouchers in this month.</div>'}</div></div>`;renderRoute()}
function openSalesMonth(month){openRegisterMonth('sales',month)}
function renderVoucherSheet(title,x){return title.toLowerCase().includes('purchase')?renderRegister('purchase',x):renderRegister('sales',x)}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
function invoiceWaitingSheet(number,message='Getting invoice details from TallyPrime…'){return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h3 style="margin:0">Invoice ${esc(number)}</h3><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div><div class="screen-loader"><span class="spinner"></span>${esc(message)}</div><div class="notice info">Waiting for the current Tally read to finish safely.</div></div></div>`}
async function openInvoice(masterId,number='',date='',party='',amount=''){if(!masterId){toast('This saved Sales Register is from an older version. It will update automatically; reopen Sales Register after the next live sync.',true);return}clearPDFURL();S.currentInvoice=null;const seq=++invoiceLoadSeq,deadline=Date.now()+45000;S.modal=invoiceWaitingSheet(number);renderRoute();try{while(seq===invoiceLoadSeq&&Date.now()<deadline){const x=await signed('/api/v1/mobile/voucher-detail?company='+encodeURIComponent(S.company)+'&masterId='+encodeURIComponent(masterId)+'&number='+encodeURIComponent(number||'')+'&date='+encodeURIComponent(date||'')+'&party='+encodeURIComponent(party||'')+'&amount='+encodeURIComponent(amount||''));if(seq!==invoiceLoadSeq)return;if(!x.pending){S.tallyOnline=!!x.live;S.modal=renderInvoiceSheet(x);return}const ms=Math.max(500,Math.min(Number(x.retryAfterMs||1000),35000));S.modal=invoiceWaitingSheet(number,x.reason==='cooldown'?`Tally is recovering safely. Invoice will open automatically in about ${Math.max(1,Math.ceil(ms/1000))} sec…`:'Another Tally read is finishing. Opening invoice automatically…');renderRoute();await wait(ms)}if(seq===invoiceLoadSeq){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h3>Invoice ${esc(number)}</h3><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div><div class="error-banner">Tally is still busy. Your Sales Register remains available; close this message and tap the invoice again.</div></div></div>`}}catch(e){if(seq===invoiceLoadSeq)S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h3>Invoice ${esc(number)}</h3><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div><div class="error-banner">${esc(e.message)}</div></div></div>`}finally{if(seq===invoiceLoadSeq)renderRoute()}}
function itemRows(items){return arr(items).length?arr(items).map((it,i)=>`<div class="mobile-card"><div class="row-title">${i+1}. ${esc(it.name||'Product')}</div><div class="kv"><div class="key">Quantity</div><div class="val">${esc(it.quantity||'-')}</div></div><div class="kv"><div class="key">Rate</div><div class="val">${esc(it.rate||'-')}</div></div><div class="kv"><div class="key">Amount</div><div class="val">${money(it.amount)}</div></div>${it.hsn?`<div class="kv"><div class="key">HSN</div><div class="val">${esc(it.hsn)}</div></div>`:''}</div>`).join(''):'<div class="empty">No product rows returned for this voucher.</div>'}
function renderInvoiceSheet(x){S.currentInvoice=x;const customer=[x.customerName,x.customerCity].filter(Boolean).join(', ');return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">Invoice ${esc(x.invoiceNumber||'')}</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}<div class="mobile-card"><div class="kv"><div class="key">Firm</div><div class="val">${esc(x.firmName||S.company)}</div></div><div class="kv"><div class="key">Customer</div><div class="val">${esc(customer||'-')}</div></div><div class="kv"><div class="key">Invoice No.</div><div class="val">${esc(x.invoiceNumber||'-')}</div></div><div class="kv"><div class="key">Invoice Date</div><div class="val">${esc(x.invoiceDate||'-')}</div></div><div class="kv"><div class="key">Dispatched Through</div><div class="val">${esc(x.dispatchedThrough||'-')}</div></div><div class="kv"><div class="key">LR/RR No.</div><div class="val">${esc(x.lrNumber||'-')}</div></div></div><div class="mobile-section">Product details</div>${itemRows(x.items)}<div class="mobile-card">${Number(x.discountAmount||0)!==0?`<div class="kv"><div class="key">Discount</div><div class="val">${money(x.discountAmount)}</div></div>`:''}<div class="kv"><div class="key">Total Amount</div><div class="val" style="font-size:17px">${money(x.totalAmount)}</div></div></div>${bankSelectMarkup()}<div class="invoice-actions"><button class="btn full-btn" data-action="share-invoice-pdf" data-master="${esc(x.masterId||'')}" data-number="${esc(x.invoiceNumber||'Invoice')}">Share Full Invoice PDF</button><button class="btn secondary full-btn" data-action="share-invoice-text">Share Details Only</button><button class="btn secondary full-btn" data-action="view-invoice-pdf" data-master="${esc(x.masterId||'')}" data-number="${esc(x.invoiceNumber||'Invoice')}">View PDF Here</button></div></div></div>`}
async function shareInvoiceText(text){if(!text)return toast('No share text is available for this invoice.',true);try{if(navigator.share){await navigator.share({title:'Dispatch Details',text});return}await navigator.clipboard.writeText(text);toast('Dispatch details copied. Paste them in WhatsApp.')}catch(e){if(e?.name!=='AbortError')toast(e.message||'Could not share text',true)}}
async function shareInvoicePDF(masterId,number){if(!masterId)return toast('Invoice PDF is unavailable until this Sales Register is refreshed.',true);try{toast('Preparing invoice PDF…');const path=withBank('/api/v1/mobile/voucher-pdf?company='+encodeURIComponent(S.company)+'&masterId='+encodeURIComponent(masterId));const blob=await invoiceBlob(masterId);const clean=(number||'Invoice').replace(/[^a-z0-9_-]+/gi,'-'),file=new File([blob],`Invoice-${clean}.pdf`,{type:'application/pdf'});if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({title:`Invoice ${number||''}`,files:[file]});return}const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);toast('PDF ready. Use your phone share options after opening it.')}catch(e){if(e?.name!=='AbortError')toast(e.message||'Could not prepare PDF',true)}}
function clearPDFURL(){previewSeq++;if(previewRenderTask){try{previewRenderTask.cancel()}catch{}previewRenderTask=null}if(previewDoc){previewDoc.destroy();previewDoc=null}invoicePDFBlob=null;invoicePDFKey='';if(S.pdfURL){try{URL.revokeObjectURL(S.pdfURL)}catch{}S.pdfURL=''}}
let previewDoc=null,previewPage=1,previewSeq=0,previewRenderTask=null;
let invoicePDFBlob=null,invoicePDFKey='';
function currentPDFKey(masterId){return [S.company,masterId,selectedBank(),S.currentInvoice?.fetchedAt||''].join('|')}
async function invoiceBlob(masterId){const key=currentPDFKey(masterId);if(invoicePDFBlob&&invoicePDFKey===key)return invoicePDFBlob;const blob=await signedBlob('/api/v1/mobile/voucher-pdf?company='+encodeURIComponent(S.company)+'&masterId='+encodeURIComponent(masterId));invoicePDFBlob=blob;invoicePDFKey=key;return blob}
async function renderPreviewPage(){const canvas=document.getElementById('actualPDFPage');if(!canvas||!previewDoc)return;const seq=previewSeq;if(previewRenderTask){try{previewRenderTask.cancel();await previewRenderTask.promise}catch{}}const page=await previewDoc.getPage(previewPage);if(seq!==previewSeq)return;const v=page.getViewport({scale:1.65});canvas.width=v.width;canvas.height=v.height;previewRenderTask=page.render({canvasContext:canvas.getContext('2d'),viewport:v});try{await previewRenderTask.promise}catch(e){if(e.name!=='RenderingCancelledException')throw e}const label=document.getElementById('pdfPageLabel');if(label)label.textContent=`Page ${previewPage} of ${previewDoc.numPages}`;document.querySelectorAll('[data-action="pdf-prev"]').forEach(b=>b.disabled=previewPage<=1);document.querySelectorAll('[data-action="pdf-next"]').forEach(b=>b.disabled=previewPage>=previewDoc.numPages)}
async function viewInvoicePDF(masterId,number){if(!S.currentInvoice)return toast('Invoice details are not loaded yet.',true);const seq=++previewSeq;S.modal=`<div class="modal"><div class="sheet"><div class="sheet-head"><h3>Preparing PDF</h3><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div><div class="screen-loader"><span class="spinner"></span>Preparing the actual invoice PDF…</div></div></div>`;renderRoute();try{const blob=await invoiceBlob(masterId);const pdfjs=await import('/assets/vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/assets/vendor/pdf.worker.min.mjs';const doc=await pdfjs.getDocument({data:new Uint8Array(await blob.arrayBuffer()),isEvalSupported:false}).promise;if(seq!==previewSeq){doc.destroy();return}previewDoc=doc;previewPage=1;S.modal=`<div class="modal pdf-modal"><div class="sheet pdf-sheet"><div class="sheet-head"><div><h3>Invoice ${esc(number)}</h3><div class="row-meta">Full invoice preview • actual PDF</div></div><button class="icon-btn" data-action="invoice-pdf-back">${icon('x')}</button></div><div class="toolbar"><button class="btn secondary" data-action="pdf-prev">Previous</button><span id="pdfPageLabel" role="status"></span><button class="btn secondary" data-action="pdf-next">Next</button></div><div class="invoice-preview-page" style="padding:0;margin-top:12px"><canvas id="actualPDFPage" style="width:100%;height:auto"></canvas></div><button class="btn full-btn" style="margin-top:12px" data-action="share-invoice-pdf" data-master="${esc(masterId)}" data-number="${esc(number)}">Share Full Invoice PDF</button></div></div>`;renderRoute();await renderPreviewPage()}catch(e){if(seq===previewSeq){S.modal=S.currentInvoice?renderInvoiceSheet(S.currentInvoice):null;renderRoute();toast(e.message,true)}}}

function renderVoucherSheet(title,x){const by={};for(const v of arr(x.vouchers)){const k=(v.date||'Unknown').slice(0,7);by[k]=(by[k]||0)+Math.abs(Number(v.amount||0))}return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${esc(title)}</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}<div class="mobile-card"><div class="metric-label">Total</div><div style="font-size:24px;font-weight:900">${money(x.total)}</div><div class="row-meta">${x.count} vouchers</div></div>${Object.entries(by).sort().reverse().map(([m,a])=>`<div class="row-card"><div class="row-title">${esc(monthLabel(m))}</div><div class="row-amount">${money(a)}</div></div>`).join('')||'<div class="empty">No vouchers returned.</div>'}</div></div>`}
function renderGenericSheet(title,x){const rows=arr(x.rows).slice(0,100);return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${esc(title)}</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}${rows.length?rows.map(r=>`<div class="mobile-card">${Object.entries(r).slice(0,12).map(([k,v])=>`<div class="kv"><div class="key">${esc(k)}</div><div class="val">${esc(v)}</div></div>`).join('')}</div>`).join(''):'<div class="empty">No normalized rows for this report.</div>'}</div></div>`}
function bankSelectMarkup(){const name=S.boot?.pdfBanks?.[(S.company||'').trim().toLowerCase()];return `<div class="row-meta" style="margin-top:10px">Bank account for customer PDFs: ${name?esc(name):'No bank details'}. Managed in desktop → PDF Bank.</div>`}

function moreView(){const last=S.boot?.lastSuccess&&!String(S.boot.lastSuccess).startsWith('0001')?new Date(S.boot.lastSuccess).toLocaleString():'Never',sync=S.sync||{},busy=syncBusy();return shell(`<div class="mobile-title">More</div><div class="mobile-card"><div class="list-row"><div><div class="row-title">Windows bridge</div><div class="row-meta">Private Tailscale connection</div></div><span class="status-pill ok">CONNECTED</span></div><div class="list-row"><div><div class="row-title">TallyPrime</div><div class="row-meta">Last successful Tally read: ${esc(last)}</div></div><span class="status-pill ${S.tallyOnline?'ok':'warn'}">${S.tallyOnline?'LIVE':'LAST UPDATED'}</span></div><div class="list-row"><div><div class="row-title">Automatic sync</div><div class="row-meta">${busy?esc((sync.company||S.company||'')+' • '+(sync.step||'Updating')):(sync.lastError?'Will retry automatically':'Safe background refresh')}</div></div><span class="status-pill ${busy?'warn':'ok'}">${busy?'RUNNING':'ON'}</span></div>${bankSelectMarkup()}</div><div class="mobile-section">Tools</div><div class="report-grid"><button class="report-btn" data-route="search">Universal Search</button><button class="report-btn" data-action="today-dispatch">Today’s Dispatch</button><button class="report-btn" data-action="open-ageing">Outstanding Ageing</button><button class="report-btn" data-route="ledgers">Customer 360</button></div><div class="mobile-section">Device</div><button class="btn secondary full-btn" data-action="unpair">Unpair this phone</button><div class="notice info" style="margin-top:14px">Customer PDFs use the selected Tally bank account when available. Accounting data remains read-only.</div>`)}
function renderRoute(){if(!S.connected)return;if(previewDoc&&document.getElementById('actualPDFPage'))return;if(S.route==='home')app.innerHTML=homeView();else if(S.route==='ledgers')app.innerHTML=ledgersView();else if(S.route==='outstanding')app.innerHTML=outstandingView();else if(S.route==='reports')app.innerHTML=reportsView();else if(S.route==='search')app.innerHTML=searchView();else app.innerHTML=moreView();bindCompany();bindBankSelect();updateTopBadge()}
async function ensureRouteData(){if(!S.connected||!S.company)return;loadBanks(true).catch(()=>{});if(S.route==='ledgers')await loadSavedLedgers();else if(S.route==='outstanding')await loadSavedOutstanding();else if(S.route==='search')await loadSearchIndex();/* navigation reads saved data only */}
function bindCompany(){const el=document.getElementById('companySelect');if(el)el.addEventListener('change',()=>{S.company=el.value;localStorage.tbHybridCompany=S.company;localStorage.tbLiveCompany=S.company;clearViewData();S.summary=(S.boot?.summaries||{})[S.company]||null;renderRoute();ensureRouteData();/* periodic desktop sync handles companies */})}
function selectedBank(){return S.boot?.pdfBanks?.[(S.company||'').trim().toLowerCase()]||''}
function withBank(path){return path}
function bindBankSelect(){}
async function loadBanks(){return null}

async function openLedger(name){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h3>${esc(name)}</h3><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div><div class="mobile-sub">Choose a report. Saved data is kept if Tally cannot refresh it.</div><div class="invoice-actions"><button class="btn full-btn" data-action="ledger-date-menu" data-ledger="${esc(name)}">Show by Date</button><button class="btn secondary full-btn" data-action="ledger-outstanding" data-ledger="${esc(name)}">Outstanding Balance</button><button class="btn secondary full-btn" data-action="customer360" data-ledger="${esc(name)}">Customer 360</button></div></div></div>`;renderRoute()}

function isoDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function ledgerPresetRange(kind){const now=new Date(),today=isoDate(now);if(kind==='today')return[today,today];if(kind==='month')return[`${today.slice(0,7)}-01`,today];if(kind==='30'){const f=new Date(now);f.setDate(f.getDate()-29);return[isoDate(f),today]}if(kind==='fy'){const y=now.getMonth()<3?now.getFullYear()-1:now.getFullYear();return[`${y}-04-01`,`${y+1}-03-31`]}return['','']}
function renderLedgerDateMenu(name){const [fyFrom,fyTo]=ledgerPresetRange('fy');return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${esc(name)}</h3><div class="row-meta">Show ledger by date</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div><div class="date-action-grid"><button class="report-btn" data-action="ledger-date-preset" data-ledger="${esc(name)}" data-period="today">Today</button><button class="report-btn" data-action="ledger-date-preset" data-ledger="${esc(name)}" data-period="month">This Month</button><button class="report-btn" data-action="ledger-date-preset" data-ledger="${esc(name)}" data-period="30">Last 30 Days</button><button class="report-btn" data-action="ledger-date-preset" data-ledger="${esc(name)}" data-period="fy">Financial Year</button></div><div class="mobile-section">Custom Date</div><div class="date-inputs"><label>From<input id="ledgerFrom" class="input" type="date" value="${fyFrom}"></label><label>To<input id="ledgerTo" class="input" type="date" value="${isoDate(new Date())}"></label></div><button class="btn full-btn" data-action="ledger-custom-run" data-ledger="${esc(name)}" style="margin-top:10px">Show Statement</button></div></div>`}
async function openLedgerStatement(name,from,to){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="screen-loader"><span class="spinner"></span>Loading ledger statement…</div></div></div>`;renderRoute();try{const q='?company='+encodeURIComponent(S.company)+'&ledger='+encodeURIComponent(name)+'&from='+encodeURIComponent(from)+'&to='+encodeURIComponent(to);const x=await signed('/api/v1/mobile/ledger-statement'+q);S.tallyOnline=!!x.live;currentLedgerReport={kind:'statement',data:x};S.modal=renderLedgerStatementSheet(x)}catch(e){toast(e.message,true);S.modal=null}finally{renderRoute()}}
function signedBalance(n){return n==null?'Unavailable':`${money(n)} ${Number(n)<0?'Dr':Number(n)>0?'Cr':''}`}
function renderLedgerStatementSheet(x){const rows=arr(x.vouchers);return `<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3>${esc(x.ledger)} • Statement</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}<div class="mobile-card"><div class="row-meta">${esc(x.fromDate)} to ${esc(x.toDate)}</div><div class="kv"><span>Opening balance</span><b>${signedBalance(x.openingBalance)}</b></div><div class="kv"><span>Debit total</span><b>${money(x.debitTotal)}</b></div><div class="kv"><span>Credit total</span><b>${money(x.creditTotal)}</b></div><div class="kv"><span>Closing balance</span><b>${signedBalance(x.closingBalance)}</b></div></div>${x.balanceNote?`<div class="notice warn">${esc(x.balanceNote)}</div>`:''}${rows.map(v=>`<div class="mobile-card"><b>${esc(v.number||v.voucherType)}</b><div class="row-meta">${esc(v.date)} • ${esc(v.voucherType)}</div><div class="kv"><span>Debit</span><b>${v.debit==null?'Not returned':money(v.debit)}</b></div><div class="kv"><span>Credit</span><b>${v.credit==null?'Not returned':money(v.credit)}</b></div><div class="kv"><span>Balance</span><b>${signedBalance(v.balance)}</b></div></div>`).join('')||'<div class="empty">No transactions in this period.</div>'}${bankSelectMarkup()}<div class="invoice-actions"><button class="btn full-btn" data-action="share-ledger-text">Share Text Details</button><button class="btn secondary full-btn" data-action="share-ledger-pdf">Share PDF</button></div></div></div>`}

async function openLedgerOutstanding(name){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="screen-loader"><span class="spinner"></span>Loading outstanding balance…</div></div></div>`;renderRoute();try{const x=await signed('/api/v1/mobile/ledger-outstanding?company='+encodeURIComponent(S.company)+'&ledger='+encodeURIComponent(name));S.tallyOnline=!!x.live;currentLedgerReport={kind:'outstanding',data:x};S.modal=renderLedgerOutstandingSheet(x)}catch(e){toast(e.message,true);S.modal=null}finally{renderRoute()}}
function renderLedgerOutstandingSheet(x){const rows=arr(x.bills),summary=x.summaryOnly?`<div class="notice info">Tally returned the ledger outstanding balance, but no bill-wise breakup for this ledger. The total below is taken from the safe Sundry Debtors/Creditors balance index.</div>`:'';return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${esc(x.ledger)} • Outstanding</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}${summary}<div class="mobile-card"><div class="metric-label">Total Outstanding</div><div style="font-size:24px;font-weight:900">${money(x.total)} ${esc(x.drCr||'')}</div><div class="row-meta">${rows.length?`${x.count} pending bill${x.count===1?'':'s'}`:'Ledger outstanding balance'}</div></div>${rows.length?rows.map(v=>`<div class="row-card"><div class="row-main"><div class="row-title">${esc(v.billNumber||'-')}</div><div class="row-meta">${esc(v.date||'')}${v.dueDate?' • Due '+esc(v.dueDate):''}${v.ageing?` • ${v.ageing} days`:''}</div></div><div class="row-amount">${money(v.pendingAmount)}</div></div>`).join(''):'<div class="empty">Bill-wise breakup was not returned by Tally for this ledger. The total balance is still shown correctly above.</div>'}${bankSelectMarkup()}<div class="invoice-actions"><button class="btn full-btn" data-action="share-ledger-text">Share Text Details</button><button class="btn secondary full-btn" data-action="share-ledger-pdf">Share PDF</button></div></div></div>`}
async function openGroup(name){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="screen-loader"><span class="spinner"></span>Loading ${esc(name)} group…</div></div></div>`;renderRoute();try{const x=await signed('/api/v1/mobile/group-balances?company='+encodeURIComponent(S.company)+'&group='+encodeURIComponent(name));S.tallyOnline=!!x.live;currentGroupReport=x;S.modal=renderGroupSheet(x)}catch(e){toast(e.message,true);S.modal=null}finally{renderRoute()}}
function renderGroupSheet(x){const rows=arr(x.ledgers);return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${esc(x.group)}</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}<div class="mobile-card"><div class="metric-label">Group Balance</div><div style="font-size:24px;font-weight:900">${money(x.total)}</div><div class="row-meta">${x.count} ledger${x.count===1?'':'s'}</div></div>${rows.length?rows.map(v=>`<div class="row-card"><div class="row-main"><div class="row-title">${esc(v.ledger)}</div><div class="row-meta">${esc(v.parent||'')}</div></div><div class="row-amount">${money(v.balance)} ${esc(v.drCr||'')}</div></div>`).join(''):'<div class="empty">No ledgers found in this group.</div>'}<div class="invoice-actions"><button class="btn full-btn" data-action="share-group-text">Share Text Details</button><button class="btn secondary full-btn" data-action="share-group-pdf">Share PDF</button></div></div></div>`}

function searchView(){const xs=arr(S.searchIndex?.results);return shell(`<div class="mobile-title">Universal Search</div><div class="mobile-sub">Search saved ledgers, customers, invoice numbers and previously opened LR/RR numbers instantly without contacting Tally.</div><input id="globalSearch" class="search" placeholder="Ledger, customer, invoice, LR/RR…" autocomplete="off"><div class="no-stale" style="margin:-4px 2px 10px">${S.searchIndex?`${S.searchIndex.count} indexed entries • ${stamp(S.searchIndex)}`:'Loading saved search index…'}</div><div id="globalSearchResults">${renderSearchResults(xs,'')}</div>`)}
async function loadSearchIndex(){if(!S.company||S.searchIndex)return;try{S.searchIndex=await signed('/api/v1/mobile/search-index?company='+encodeURIComponent(S.company));renderRoute()}catch(e){S.error=e.message;renderRoute()}}
function renderSearchResults(xs,q){q=(q||'').trim().toLowerCase();const f=arr(xs).filter(x=>!q||`${x.title} ${x.subtitle} ${x.party} ${x.number} ${x.lrNumber} ${x.ledger}`.toLowerCase().includes(q)).slice(0,120);if(!f.length)return`<div class="empty">${q?'No matching saved results.':'Type to search, or browse the saved index below.'}</div>`;return f.map(x=>{const invoice=x.masterId?`data-action="invoice-open" data-master="${esc(x.masterId)}" data-number="${esc(x.number||'')}" data-date="${esc(x.date||'')}" data-party="${esc(x.party||'')}" data-amount="${esc(x.amount||0)}"`:`data-action="customer360" data-ledger="${esc(x.ledger||x.title)}"`;return`<button class="row-card row-button" ${invoice}><div class="row-main"><div class="row-title">${esc(x.title||'-')}</div><div class="row-meta">${esc((x.kind||'').toUpperCase())}${x.subtitle?' • '+esc(x.subtitle):''}${x.lrNumber?' • LR/RR '+esc(x.lrNumber):''}</div></div>${Number(x.amount||0)?`<div class="row-amount">${money(x.amount)}</div>`:''}</button>`}).join('')}

async function openTodayDispatch(){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="screen-loader"><span class="spinner"></span>Loading today’s dispatch…</div></div></div>`;renderRoute();try{const x=await signed('/api/v1/mobile/today-dispatch?company='+encodeURIComponent(S.company)+'&refresh=1');S.todayDispatch=x;S.tallyOnline=!!x.live;S.modal=renderTodayDispatch(x)}catch(e){toast(e.message,true);S.modal=null}finally{renderRoute()}}
function renderTodayDispatch(x){const rows=arr(x.vouchers);return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">Today’s Dispatch</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}<div class="mobile-card"><div class="metric-label">Today</div><div style="font-size:24px;font-weight:900">${money(x.total)}</div><div class="row-meta">${x.count} sales invoice${x.count===1?'':'s'}</div></div>${rows.length?rows.map(v=>`<button class="row-card row-button" data-action="invoice-open" data-master="${esc(v.masterId||'')}" data-number="${esc(v.number||'')}" data-date="${esc(v.date||'')}" data-party="${esc(v.party||'')}" data-amount="${esc(v.amount||0)}"><div class="row-main"><div class="row-title">${esc(v.number||'Invoice')}</div><div class="row-meta">${esc(v.party||'')} • ${esc(v.date||'')}</div></div><div class="row-amount">${money(v.amount)}</div></button>`).join(''):'<div class="empty">No sales invoices found for today.</div>'}</div></div>`}

async function openAgeing(){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="screen-loader"><span class="spinner"></span>Building saved ageing dashboard…</div></div></div>`;renderRoute();try{const x=await signed('/api/v1/mobile/ageing?company='+encodeURIComponent(S.company));S.ageing=x;S.modal=renderAgeing(x)}catch(e){toast(e.message,true);S.modal=null}finally{renderRoute()}}
function renderAgeing(x){return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">Outstanding Ageing</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div><div class="mobile-card"><div class="metric-label">Known bill-wise outstanding</div><div style="font-size:24px;font-weight:900">${money(x.total)}</div><div class="row-meta">${x.billCount} bills • coverage ${x.coveredParties}/${x.totalParties||0} parties (${x.coveragePercent||0}%)</div></div>${arr(x.buckets).map(b=>`<div class="row-card"><div class="row-main"><div class="row-title">${esc(b.label)}</div><div class="row-meta">${b.bills} bills</div></div><div class="row-amount">${money(b.amount)}</div></div>`).join('')}<div class="notice info">Ageing is built from bill-wise party details already read safely. Open a party from Outstanding to add/update that party without running a large all-party Tally batch.</div></div></div>`}

async function openCustomer360(name){S.modal=`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="screen-loader"><span class="spinner"></span>Building Customer 360…</div></div></div>`;renderRoute();try{await loadBanks(true);const x=await signed('/api/v1/mobile/customer360?company='+encodeURIComponent(S.company)+'&ledger='+encodeURIComponent(name)+'&refresh=1');S.currentCustomer=x;S.tallyOnline=!!x.live;S.modal=renderCustomer360(x)}catch(e){toast(e.message,true);S.modal=null}finally{renderRoute()}}
function renderCustomer360(x){const inv=arr(x.latestInvoices),act=arr(x.recentActivity);return`<div class="modal"><div class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><div><h3 style="margin:0">${esc(x.ledger)} • 360</h3><div class="live-stamp">${stamp(x)}</div></div><button class="icon-btn" data-action="close-modal">${icon('x')}</button></div>${dataBanner(x)}<div class="summary-grid"><div class="summary-card"><div class="k">Outstanding</div><div class="v">${money(x.outstanding)}</div><div class="s">${x.pendingBillCount||0} known bills</div></div><div class="summary-card"><div class="k">Overdue</div><div class="v">${money(x.overdue)}</div><div class="s">Based on known bill details</div></div></div>${x.lastPayment?`<div class="mobile-card"><div class="metric-label">Last Payment</div><div style="font-size:20px;font-weight:900">${money(x.lastPayment.amount)}</div><div class="row-meta">${esc(x.lastPayment.date||'')} • ${esc(x.lastPayment.number||x.lastPayment.voucherType||'')}</div></div>`:''}<div class="mobile-section">Latest invoices</div>${inv.length?inv.map(v=>`<button class="row-card row-button" data-action="invoice-open" data-master="${esc(v.masterId||'')}" data-number="${esc(v.number||'')}" data-date="${esc(v.date||'')}" data-party="${esc(v.party||'')}" data-amount="${esc(v.amount||0)}"><div class="row-main"><div class="row-title">${esc(v.number||'Invoice')}</div><div class="row-meta">${esc(v.date||'')}</div></div><div class="row-amount">${money(v.amount)}</div></button>`).join(''):'<div class="empty">No recent invoices in the saved sales register.</div>'}<div class="mobile-section">Recent activity</div>${act.length?act.slice(0,6).map(v=>`<div class="row-card"><div class="row-main"><div class="row-title">${esc(v.number||v.voucherType||'Voucher')}</div><div class="row-meta">${esc(v.date||'')} • ${esc(v.voucherType||'')}</div></div><div class="row-amount">${money(v.amount)}</div></div>`).join(''):'<div class="empty">No recent ledger activity returned.</div>'}${bankSelectMarkup()}<div class="invoice-actions"><button class="btn full-btn" data-action="share-customer-text">Share 360 Text</button><button class="btn secondary full-btn" data-action="share-customer-pdf">Share Statement PDF</button><button class="btn secondary full-btn" data-action="ledger-date-menu" data-ledger="${esc(x.ledger)}">Ledger by Date</button><button class="btn secondary full-btn" data-action="ledger-outstanding" data-ledger="${esc(x.ledger)}">Outstanding Bills</button></div></div></div>`}

async function shareTextValue(title,text){if(!text)return toast('Nothing to share.',true);try{if(navigator.share){await navigator.share({title,text});return}await navigator.clipboard.writeText(text);toast('Details copied. Paste them in WhatsApp.')}catch(e){if(e?.name!=='AbortError')toast(e.message||'Could not share text',true)}}
async function sharePDFPath(path,filename,title){try{toast('Preparing PDF…');const blob=await signedBlob(path);const file=new File([blob],filename,{type:'application/pdf'});if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({title,files:[file]});return}const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);toast('PDF ready.')}catch(e){if(e?.name!=='AbortError')toast(e.message||'Could not prepare PDF',true)}}
async function probeTally(){if(S.loading)return;S.loading='probe';toast('Testing Tally connection…');try{const x=await signed('/api/v1/mobile/probe',{method:'POST',body:'{}'});S.tallyOnline=!!x.tallyOnline;if(x.companies?.length){S.boot.companies=x.companies;if(!S.company){S.company=x.companies[0].name;localStorage.tbHybridCompany=S.company}}toast(S.tallyOnline?'TallyPrime is live':'Tally unavailable — saved data remains available',!S.tallyOnline)}catch(e){toast(e.message,true)}finally{S.loading='';renderRoute()}}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-route],[data-action]');if(!b)return;if(b.dataset.route){S.route=b.dataset.route;location.hash=S.route;clearPDFURL();invoiceLoadSeq++;S.modal=null;S.error='';renderRoute();ensureRouteData();return}const a=b.dataset.action;if(a==='retry')await boot(false).catch(()=>{});else if(a==='pair')await doPair();else if(a==='set-pin')await setPhonePin();else if(a==='unlock')await unlockPhone();else if(a==='reset-lock'){if(confirm('Reset this phone app? You will need a new pairing code from the PC.')){clearCreds();clearViewData();S.connected=false;await boot(false)}}else if(a==='unpair'){if(confirm('Unpair this phone?')){clearCreds();clearViewData();await boot(false)}}else if(a==='summary')await loadSummary();else if(a==='load-one')await loadOne(b.dataset.kind);else if(a==='load-ledgers')await loadLedgers();else if(a==='ledger-tab'){ledgerTab=b.dataset.type||'ledgers';renderRoute()}else if(a==='ledger-open')await openLedger(b.dataset.ledger);else if(a==='customer360')await openCustomer360(b.dataset.ledger);else if(a==='ledger-date-menu'){S.modal=renderLedgerDateMenu(b.dataset.ledger);renderRoute()}else if(a==='ledger-date-preset'){const [f,t]=ledgerPresetRange(b.dataset.period);await openLedgerStatement(b.dataset.ledger,f,t)}else if(a==='ledger-custom-run'){const f=document.getElementById('ledgerFrom')?.value||'',t=document.getElementById('ledgerTo')?.value||'';if(!f||!t)return toast('Select From and To dates.',true);await openLedgerStatement(b.dataset.ledger,f,t)}else if(a==='ledger-outstanding')await openLedgerOutstanding(b.dataset.ledger);else if(a==='share-ledger-text')await shareTextValue(currentLedgerReport?.kind==='outstanding'?'Outstanding Balance':'Ledger Statement',currentLedgerReport?.data?.shareText||'');else if(a==='share-ledger-pdf'){const r=currentLedgerReport;if(!r)return;const d=r.data;if(r.kind==='outstanding')await sharePDFPath(withBank('/api/v1/mobile/ledger-outstanding-pdf?company='+encodeURIComponent(S.company)+'&ledger='+encodeURIComponent(d.ledger)),`Outstanding-${(d.ledger||'Ledger').replace(/[^a-z0-9_-]+/gi,'-')}.pdf`,'Outstanding Balance');else await sharePDFPath(withBank('/api/v1/mobile/ledger-statement-pdf?company='+encodeURIComponent(S.company)+'&ledger='+encodeURIComponent(d.ledger)+'&from='+encodeURIComponent(d.fromDate)+'&to='+encodeURIComponent(d.toDate)),`Ledger-${(d.ledger||'Ledger').replace(/[^a-z0-9_-]+/gi,'-')}.pdf`,'Ledger Statement')}else if(a==='group-open')await openGroup(b.dataset.group);else if(a==='share-group-text')await shareTextValue('Ledger Group Details',currentGroupReport?.shareText||'');else if(a==='share-group-pdf'){const g=currentGroupReport;if(g)await sharePDFPath('/api/v1/mobile/group-balances-pdf?company='+encodeURIComponent(S.company)+'&group='+encodeURIComponent(g.group),`Group-${(g.group||'Group').replace(/[^a-z0-9_-]+/gi,'-')}.pdf`,'Ledger Group Details')}else if(a==='out-tab'){outType=b.dataset.type;S.error='';renderRoute();await loadSavedOutstanding()}else if(a==='load-outstanding')await loadOutstanding();else if(a==='party-outstanding')await openPartyOutstanding(b.dataset.party);else if(a==='goto-payable'){outType='payable';S.route='outstanding';location.hash='outstanding';renderRoute();await loadSavedOutstanding()}else if(a==='report')await openReport(b.dataset.report);else if(a==='today-dispatch')await openTodayDispatch();else if(a==='open-ageing')await openAgeing();else if(a==='register-month-open')openRegisterMonth(b.dataset.kind||'sales',b.dataset.month);else if(a==='sales-month-open')openSalesMonth(b.dataset.month);else if(a==='register-back'){S.modal=renderRegister(currentRegister,currentRegister==='purchase'?(S.purchases||{vouchers:[],total:0,count:0}):(S.sales||{vouchers:[],total:0,count:0}));renderRoute()}else if(a==='sales-register-back'){S.modal=renderSalesRegister(S.sales||{vouchers:[],total:0,count:0});renderRoute()}else if(a==='invoice-open')await openInvoice(b.dataset.master,b.dataset.number,b.dataset.date,b.dataset.party,b.dataset.amount);else if(a==='pdf-prev'){if(previewDoc&&previewPage>1){previewPage--;await renderPreviewPage()}}else if(a==='pdf-next'){if(previewDoc&&previewPage<previewDoc.numPages){previewPage++;await renderPreviewPage()}}else if(a==='share-invoice-text')await shareInvoiceText(S.currentInvoice?.shareText||'');else if(a==='share-invoice-pdf')await shareInvoicePDF(b.dataset.master,b.dataset.number);else if(a==='view-invoice-pdf')await viewInvoicePDF(b.dataset.master,b.dataset.number);else if(a==='invoice-pdf-back'){clearPDFURL();S.modal=S.currentInvoice?renderInvoiceSheet(S.currentInvoice):null;renderRoute()}else if(a==='share-customer-text')await shareTextValue('Customer 360',S.currentCustomer?.shareText||'');else if(a==='share-customer-pdf'){const x=S.currentCustomer;if(x)await sharePDFPath(withBank('/api/v1/mobile/customer360-pdf?company='+encodeURIComponent(S.company)+'&ledger='+encodeURIComponent(x.ledger)),`Customer-${(x.ledger||'Customer').replace(/[^a-z0-9_-]+/gi,'-')}.pdf`,'Customer 360 Statement')}else if(a==='close-modal'){invoiceLoadSeq++;clearPDFURL();S.currentInvoice=null;S.modal=null;renderRoute()}else if(a==='probe')await probeTally()});
app.addEventListener('input',e=>{if(e.target.id==='ledgerSearch'){const box=document.getElementById('ledgerList');if(!box)return;box.innerHTML=ledgerTab==='groups'?renderGroupRows(ledgerGroups(),e.target.value):renderLedgerRows(S.ledgers?.ledgers||[],e.target.value)}else if(e.target.id==='globalSearch'){const box=document.getElementById('globalSearchResults');if(box)box.innerHTML=renderSearchResults(S.searchIndex?.results||[],e.target.value)}});
window.addEventListener('hashchange',()=>{S.route=(location.hash||'#home').slice(1);if(!validRoutes.includes(S.route))S.route='home';clearPDFURL();S.currentInvoice=null;S.modal=null;if(S.connected){renderRoute();ensureRouteData()}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){markPhoneLocked();return}if(document.visibilityState==='visible'&&creds().id&&!S.loading)boot(true,false).catch(()=>{})});window.addEventListener('pagehide',markPhoneLocked);
async function statusPoll(){if(document.visibilityState!=='visible'||!creds().id)return;if(phoneIsLocked()){try{await verifyDeviceAuthorization()}catch{}return}if(!S.connected){try{await boot(false)}catch{}return}try{const before=String(S.boot?.cacheLatestAt||S.boot?.cache?.latestAt||'');const beforeSync=JSON.stringify(S.sync||{});const st=await signed('/api/v1/mobile/status');S.tallyOnline=!!st.tallyOnline;S.sync=st.autoSync||S.sync;const syncChanged=beforeSync!==JSON.stringify(S.sync||{});S.boot={...(S.boot||{}),...st};const cs=arr(st.companies);let picked=false;if(!S.company&&cs.length){S.company=cs[0].name;localStorage.tbHybridCompany=S.company;localStorage.tbLiveCompany=S.company;picked=true}if(st.summaries)S.summary=st.summaries[S.company]||S.summary;const after=String(st.cacheLatestAt||'');const changed=after&&after!==before;if(changed||picked){if(S.route==='ledgers'){S.ledgers=null;await loadSavedLedgers()}else if(S.route==='outstanding'){if(outType==='payable')S.payable=null;else S.receivable=null;await loadSavedOutstanding()}else renderRoute();/* company discovery is handled by desktop sync */}else{updateTopBadge();if(S.route==='home'||S.route==='more'||(syncChanged&&((S.route==='ledgers'&&!S.ledgers)||(S.route==='outstanding'&&!(outType==='payable'?S.payable:S.receivable)))))renderRoute()}}catch(e){if(e.revoked)await showPairAfterRevocation();else if(e.auth)renderAuthProblem(e.message);else{S.connected=false;renderBridgeOffline(e.message)}}}
boot(false).catch(()=>{});setInterval(statusPoll,5000);
